arguments.command:
cd /app/quoter && python - <<'EOF'
import re
def sub(path, pairs):
    s = open(path).read()
    for a, b in pairs:
        if a not in s: raise SystemExit(f"missing in {path}: {a!r}")
        s = s.replace(a, b)
    open(path, "w").write(s)

# settings
s = open("settings.py").read()
i = s.index("SETTINGS = Settings()")
s = s[:i] + '''def make(**values) -> Settings:
    """A new Settings: the fallback values, then each given value converted and
    checked by parse_value."""
    return Settings(**{name: parse_value(name, raw) for name, raw in values.items()})
'''
s = s.replace("@dataclass\nclass Settings", "@dataclass(frozen=True)\nclass Settings")
s = s.replace('''One Settings object, SETTINGS, holds the configuration for the whole process.
The command line fills it in with configure() from the config file, the
environment and the command-line options; library code reads it where it
needs a value.
''', '''A Settings value is immutable and is passed explicitly, as the parameter
`conf`, to the code that needs it. make() builds one from raw values; the
command line builds one from the config file, the environment and the
command-line options.
''')
open("settings.py","w").write(s)

sub("core/money.py", [
 ("from quoter import settings\n\n", "\n"),
 ("def round_money(value: Decimal)", "def round_money(conf, value: Decimal)"),
 ("    conf = settings.current()\n", ""),
 ("def format_money(value: Decimal, currency: str | None = None) -> str:\n    code = currency or settings.SETTINGS.currency",
  "def format_money(conf, value: Decimal, currency: str | None = None) -> str:\n    code = currency or conf.currency"),
])

sub("core/timeutil.py", [
 ("import date, timedelta\n\nfrom quoter import settings as _settings\n", "import date, timedelta\nimport functools\n"),
 ("def pricing_date() -> date:\n    return date.fromisoformat(_settings.SETTINGS.pricing_date)",
  "def pricing_date(conf) -> date:\n    return date.fromisoformat(conf.pricing_date)"),
 ('''def _closed_days() -> frozenset:
    """Holiday dates of the pricing year and the year after it."""
    year = pricing_date().year
    return frozenset(date(y, m, d) for y in (year, year + 1) for m, d in HOLIDAYS)


CLOSED = _closed_days()


def is_delivery_day(day: date) -> bool:
    if day in CLOSED:''', '''@functools.lru_cache(maxsize=None)
def _closed_in(year: int) -> frozenset:
    return frozenset(date(y, m, d) for y in (year, year + 1) for m, d in HOLIDAYS)


def closed_days(conf) -> frozenset:
    """Holiday dates of the pricing year and the year after it."""
    return _closed_in(pricing_date(conf).year)


def is_delivery_day(conf, day: date) -> bool:
    if day in closed_days(conf):'''),
 ("return _settings.SETTINGS.saturday_delivery", "return conf.saturday_delivery"),
 ("def add_delivery_days(start", "def add_delivery_days(conf, start"),
 ("is_delivery_day(current)", "is_delivery_day(conf, current)"),
])

sub("core/units.py", [
 ('''from quoter.settings import SETTINGS

if SETTINGS.units == "imperial":
    WEIGHT_FACTOR = Decimal("0.45359237")
    LENGTH_FACTOR = Decimal("2.54")
else:
    WEIGHT_FACTOR = Decimal(1)
    LENGTH_FACTOR = Decimal(1)

MAX_INPUT_KG = Decimal(1000)


def to_kg(value: Decimal) -> Decimal:
    return value * WEIGHT_FACTOR


def to_cm(value: Decimal) -> Decimal:
    return value * LENGTH_FACTOR
''', '''MAX_INPUT_KG = Decimal(1000)


def weight_factor(conf) -> Decimal:
    if conf.units == "imperial":
        return Decimal("0.45359237")
    return Decimal(1)


def length_factor(conf) -> Decimal:
    if conf.units == "imperial":
        return Decimal("2.54")
    return Decimal(1)


def to_kg(conf, value: Decimal) -> Decimal:
    return value * weight_factor(conf)


def to_cm(conf, value: Decimal) -> Decimal:
    return value * length_factor(conf)
'''),
])

sub("services/cache.py", [
 ("from quoter.settings import current\n\n", ""),
 ('''    """Cache fn's results by its positional arguments, which must be hashable.

    Caching is skipped while the `cache_enabled` setting is off."""

    @functools.wraps(fn)
    def wrapper(*args):
        if not current().cache_enabled:
            return fn(*args)
        key = (fn.__qualname__,) + args
        if key in _STORE:
            _HITS[0] += 1
            return _STORE[key]
        value = fn(*args)''', '''    """Cache fn's results by its positional arguments, which must be hashable.
    The first argument is the settings, so a result is only reused for equal
    settings.

    Caching is skipped while the `cache_enabled` setting is off."""

    @functools.wraps(fn)
    def wrapper(conf, *args):
        if not conf.cache_enabled:
            return fn(conf, *args)
        key = (fn.__qualname__, conf) + args
        if key in _STORE:
            _HITS[0] += 1
            return _STORE[key]
        value = fn(conf, *args)'''),
])

sub("services/trace.py", [
 ("from quoter import settings\n\n\n", "\n"),
 ("on = settings.SETTINGS.debug or", "on = args[0].debug or"),
 ("for a in args[1:])", "for a in args[2:])"),
])

sub("services/quotes.py", [
 ("from quoter.settings import SETTINGS\n", ""),
 ("def make_request(origin", "def make_request(conf, origin"),
 ("units.to_kg(units.parse_weight(weight))", "units.to_kg(conf, units.parse_weight(weight))"),
 ("units.to_cm(v)", "units.to_cm(conf, v)"),
 ("def quote_service(req", "def quote_service(conf, req"),
 ("choose_box(req.dims)", "choose_box(conf, req.dims)"),
 ("dimsmod.chargeable_kg(actual, outer)", "dimsmod.chargeable_kg(conf, actual, outer)"),
 ("zones.zone_for(req.origin", "zones.zone_for(conf, req.origin"),
 ("carrier.base_price(zone", "carrier.base_price(conf, zone"),
 ("carrier.markup_pct()", "carrier.markup_pct(conf)"),
 ("surcharges.applicable(req", "surcharges.applicable(conf, req"),
 ("surcharges.total(kinds)", "surcharges.total(conf, kinds)"),
 ("fuel.fuel_charge(base", "fuel.fuel_charge(conf, base"),
 ("insurance.premium(req", "insurance.premium(conf, req"),
 ("round_money(base +", "round_money(conf, base +"),
 ("tax.apply_tax(net, tax.rate_for(req", "tax.apply_tax(conf, net, tax.rate_for(conf, req"),
 ("currency = SETTINGS.currency", "currency = conf.currency"),
 ("round_money(fx.convert(gross, currency))", "round_money(conf, fx.convert(conf, gross, currency))"),
 ("timeutil.add_delivery_days(timeutil.pricing_date(),", "timeutil.add_delivery_days(conf, timeutil.pricing_date(conf),"),
 ("def quote_all(req", "def quote_all(conf, req"),
 ("registry.enabled()", "registry.enabled(conf)"),
 ("quote_service(req, c.name", "quote_service(conf, req, c.name"),
 ("def cheapest(req: QuoteRequest):\n    quotes = quote_all(req)", "def cheapest(conf, req: QuoteRequest):\n    quotes = quote_all(conf, req)"),
])

sub("services/batch.py", [
 ("def run_batch(path", "def run_batch(conf, path"),
 ("make_request(\n                row", "make_request(\n                conf,\n                row"),
 ("cheapest(req)", "cheapest(conf, req)"),
 ("discount_pct(len", "discount_pct(conf, len"),
 ("apply_tax(net_total", "apply_tax(conf, net_total"),
])
EOF
grep -n "round_money" quoter 2>/dev/null; grep -rn "tax.rate_for\|apply_tax" services/quotes.py

